+        public int PhysicalHeadingIntent(ManualSkiHeadingState pose,SkiPlanarVelocity velocity,double forwardX,double forwardZ)
+        {
+            PhysiologyNumbers.RequireRange(forwardX,-1,1,nameof(forwardX));
+            PhysiologyNumbers.RequireRange(forwardZ,-1,1,nameof(forwardZ));
+            if(!pose.IsValid||Math.Abs(forwardX*forwardX+forwardZ*forwardZ-1)>1e-12)
+                throw new ArgumentException("Owned unit target direction required.");
+            double speed=Math.Sqrt(velocity.X*velocity.X+velocity.Z*velocity.Z);
+            double direction=speed>PhysiologyNumbers.MinimumPositive?Math.Atan2(velocity.X,velocity.Z):pose.HeadingRadians;
+            double delta=Math.Atan2(forwardX,forwardZ)-direction;
+            double error=Math.Atan2(Math.Sin(delta),Math.Cos(delta));
+            double desired=error/policy.HeadingResponseSeconds-policy.YawRateFeedback*pose.YawRateRadiansPerSecond;
+            double response=ManualSkiSteeringSystem.GetRequest(physicalCommands,ManualSkiCommand.SteeringUnits,speed,PhysiologyNumbers.MaximumMagnitude).RequestedYawRate;
+            double forward=Math.Abs(velocity.X*Math.Sin(pose.HeadingRadians)+velocity.Z*Math.Cos(pose.HeadingRadians));
+            double rollingScale=speed>PhysiologyNumbers.MinimumPositive?Math.Max(forward,lowSpeedReference)/Math.Max(forward,PhysiologyNumbers.MinimumPositive):1;
+            return (int)Math.Round(Math.Max(-1,Math.Min(1,desired*rollingScale/response))*ManualSkiCommand.SteeringUnits,MidpointRounding.ToEven);
+        }
     }
 }
